args.command:
/bin/bash -lc "node --input-type=module <<'NODE'
import assert from 'node:assert/strict'
import { readFileSync } from 'node:fs'
import { createRequire } from 'node:module'
import ts from 'typescript'
import { renderToStaticMarkup } from 'react-dom/server'

const requestHeaders = new Headers({
  host: 'example.test',
  'x-forwarded-proto': 'https',
  cookie: 'session=test-session',
  authorization: 'Bearer test-token',
})
const require = createRequire(import.meta.url)
const source = readFileSync('app/UserProfile.tsx', 'utf8')
const { outputText } = ts.transpileModule(source, {
  compilerOptions: { module: ts.ModuleKind.CommonJS, jsx: ts.JsxEmit.ReactJSX },
})
const module = { exports: {} }
new Function('require', 'module', 'exports', outputText)(
  (name) => name === 'next/headers' ? { headers: async () => requestHeaders } : require(name),
  module,
  module.exports,
)
const UserProfile = module.exports.default
const originalFetch = globalThis.fetch
try {
  let requests = 0
  globalThis.fetch = async (url, options) => {
    requests++
    assert.equal(url, 'https://example.test/api/users/profile')
    assert.equal(options.cache, 'no-store')
    assert.equal(options.headers.get('cookie'), 'session=test-session')
    assert.equal(options.headers.get('authorization'), 'Bearer test-token')
    return Response.json({ name: 'Alex Smith', email: 'alex@example.test' })
  }
  let html = renderToStaticMarkup(await UserProfile())
  assert.equal(requests, 1)
  assert.match(html, /Name: Alex Smith/)
  assert.match(html, /Email: alex@example.test/)
  console.log('PASS: profile renders name and email using the current session')

  for (const [label, fetchResult] of [
    ['HTTP error', async () => new Response(null, { status: 401 })],
    ['network error', async () => { throw new Error('unavailable') }],
    ['invalid JSON', async () => new Response('invalid')],
    ['missing profile fields', async () => Response.json({ name: 'Alex' })],
  ]) {
    globalThis.fetch = fetchResult
    html = renderToStaticMarkup(await UserProfile())
    assert.match(html, /Unable to load user profile/)
    console.log("'`PASS: ${label} renders the fallback`)
  }
} finally {
  globalThis.fetch = originalFetch
}
NODE'

